    check('runtime-manifests','Connect manifests',issues.some(x=>x.code.startsWith('manifest-'))?'warning':'pass',kernelConnectManifests.size);
    check('event-lifecycle','Event subscriptions',issues.some(x=>x.code.startsWith('event-subscription-'))?'warning':'pass',kernelEventSubscriptions.size);
