      if(!saved||saved.sessionOnly)throw new Error('Browser Vault offered only temporary session storage. A persistent safety copy is required.');
      const stored=await curioidVault.get(saved.id);
      if(!stored?.blob||Number(stored.size)!==byteLength)throw new Error('The saved safety copy could not be read back with its original size.');
      if(await stored.blob.text()!==serialized)throw new Error('The safety copy failed exact read-back verification.');
      window.dispatchEvent(new CustomEvent('curioid:vault-notice',{detail:{message:`Safety copy saved and verified: ${saved.name}.`}}));
