      const nextManifest=kernelConnectPrepareManifestUpdate(capability.ownerExperienceId,manifest=>{manifest.provides.capabilities=manifest.provides.capabilities.filter(item=>item.id!==key);return manifest;});
      if(!nextManifest)throw new Error('The capability owner is no longer active. The registry was left unchanged.');
