    const theme=CURIOID_OS_SIMPLE_THEMES[b.theme];
    const recordModules=curioidOsResolveSimpleModules(b);
    const labels={notes:'Notes',tasks:'Tasks',planner:'Planner',bookmarks:'Bookmarks',collections:'Collections',calculator:'Calculator',focus:'Focus timer'};
    const icons={notes:'✎',tasks:'✓',planner:'▦',bookmarks:'◇',collections:'▤',calculator:'＋',focus:'◷'};
    for(const module of recordModules){labels[module.id]=module.name;icons[module.id]=module.icon||'▦';}
    const field=(id,label,type='text',extra='')=>`<label for="${id}">${label}<input id="${id}" data-os-id="${id}" type="${type}" ${extra}></label>`;
    const area=(id,label,extra='')=>`<label for="${id}">${label}<textarea id="${id}" data-os-id="${id}" ${extra}></textarea></label>`;
    const button=(id,label,primary=false)=>`<button type="button" id="${id}" data-os-id="${id}" ${primary?'class="primary"':''}>${label}</button>`;
    const list=(id)=>`<pre class="simple-list" id="${id}" data-os-id="${id}" aria-live="polite">Nothing here yet.</pre>`;
    const indexField=(id)=>field(id,'Item number','number','min="1" step="1" inputmode="numeric" placeholder="1"');
    const panels={
      notes:`<section class="simple-app" id="panel-notes" data-app-panel="notes"><div class="app-heading"><div><small>CAPTURE / REMEMBER</small><h2>Notes</h2><p>Keep thoughts, drafts and little discoveries.</p></div></div><div class="form-grid">${field('note-title','Title','text','maxlength="100" placeholder="A thought worth keeping"')}${area('note-body','Your note','rows="5" maxlength="12000" placeholder="Write anything…" class="wide"')}</div><div class="app-actions">${button('note-save','Save note',true)}${indexField('note-index')}${button('note-delete','Delete selected')}</div>${list('notes-list')}</section>`,
      tasks:`<section class="simple-app" id="panel-tasks" data-app-panel="tasks" hidden><div class="app-heading"><div><small>DO / MAKE PROGRESS</small><h2>Tasks</h2><p>Keep the next small step visible.</p></div><span class="app-count" id="task-count" data-os-id="task-count">0 open</span></div><div class="form-grid inline-form">${field('task-input','New task','text','maxlength="240" placeholder="What would you like to get done?"')}${field('task-date','Due date','date')}</div><div class="app-actions">${button('task-add','Add task',true)}${indexField('task-index')}${button('task-toggle','Complete / reopen')}${button('task-delete','Delete selected')}</div>${list('tasks-list')}</section>`,
      planner:`<section class="simple-app" id="panel-planner" data-app-panel="planner" hidden><div class="app-heading"><div><small>TIME / INTENTION</small><h2>Planner</h2><p>Give your plans a place to land.</p></div></div><div class="form-grid">${field('plan-title','Plan or event','text','maxlength="160" placeholder="What is happening?"')}${field('plan-date','Date','date')}${field('plan-time','Time','time')}${area('plan-details','Details','rows="3" maxlength="3000" class="wide" placeholder="Optional details…"')}</div><div class="app-actions">${button('plan-add','Save plan',true)}${indexField('plan-index')}${button('plan-delete','Delete selected')}</div>${list('planner-list')}</section>`,
      bookmarks:`<section class="simple-app" id="panel-bookmarks" data-app-panel="bookmarks" hidden><div class="app-heading"><div><small>COLLECT / RETURN</small><h2>Bookmarks</h2><p>Keep useful links in one quiet place.</p></div></div><div class="form-grid">${field('bookmark-title','Label','text','maxlength="100" placeholder="Website or resource"')}${field('bookmark-url','Web address','url','maxlength="1200" placeholder="https://example.com"')}</div><div class="app-actions">${button('bookmark-add','Save bookmark',true)}${indexField('bookmark-index')}${button('bookmark-copy','Copy URL')}${button('bookmark-delete','Delete selected')}</div>${list('bookmarks-list')}</section>`,
      collections:`<section class="simple-app" id="panel-collections" data-app-panel="collections" hidden><div class="app-heading"><div><small>GATHER / ORGANIZE</small><h2>Collections</h2><p>Build lists for ideas, books, recipes, places or anything else.</p></div></div><div class="form-grid">${field('collection-name','Collection name','text','maxlength="100" placeholder="Things to explore"')}${field('collection-item','First item','text','maxlength="500" placeholder="Add an item"')}</div><div class="app-actions">${button('collection-add','Add to collection',true)}${indexField('collection-index')}${button('collection-delete','Delete selected')}</div>${list('collections-list')}</section>`,
      calculator:`<section class="simple-app" id="panel-calculator" data-app-panel="calculator" hidden><div class="app-heading"><div><small>QUICK / CALCULATE</small><h2>Calculator</h2><p>Basic arithmetic with parentheses and decimals.</p></div></div><div class="calculator-box">${field('calc-expression','Expression','text','maxlength="120" inputmode="decimal" value="12 × 4" placeholder="(12 + 8) / 2"')}<div class="calculator-result" id="calc-result" data-os-id="calc-result" aria-live="polite">48</div><div class="app-actions">${button('calc-run','Calculate',true)}${button('calc-clear','Clear')}</div><small class="subtle">Use + − * / % and parentheses. Nothing is sent anywhere.</small></div></section>`,
      focus:`<section class="simple-app" id="panel-focus" data-app-panel="focus" hidden><div class="app-heading"><div><small>FOCUS / BREATHE</small><h2>Focus timer</h2><p>Choose a short stretch of time and give one thing your attention.</p></div></div><div class="focus-box">${field('focus-minutes','Minutes','number','min="1" max="180" step="1" value="25"')}<output id="focus-display" data-os-id="focus-display">25:00</output><div class="app-actions">${button('focus-start','Start',true)}${button('focus-pause','Pause')}${button('focus-reset','Reset')}</div><p id="focus-status" data-os-id="focus-status" class="subtle" aria-live="polite">Ready when you are.</p></div></section>`
    };
    const genericPanels=Object.create(null);
    const genericControl=(module,fieldDef)=>{
      const id=`module-field-${module.id}-${fieldDef.id}`,label=curioidOsEscape(fieldDef.label),required=fieldDef.required?' required':'',max=fieldDef.type==='textarea'||fieldDef.type==='select'||fieldDef.type==='checkbox'?'':` maxlength="${Math.max(1,Math.min(5000,fieldDef.maxLength||500))}"`;
      if(fieldDef.type==='textarea')return `<label class="wide" for="${id}">${label}<textarea id="${id}" data-os-id="${id}" rows="3"${required}${max}></textarea></label>`;
      if(fieldDef.type==='select'){const options=(fieldDef.options||[]).map(option=>`<option value="${curioidOsEscape(option.value)}">${curioidOsEscape(option.label)}</option>`).join('');return `<label for="${id}">${label}<select id="${id}" data-os-id="${id}"${required}><option value="">Choose…</option>${options}</select></label>`;}
      if(fieldDef.type==='checkbox')return `<label class="module-check" for="${id}"><input id="${id}" data-os-id="${id}" type="checkbox"> ${label}</label>`;
      const type=['number','date','datetime-local','url','email','tel','color'].includes(fieldDef.type)?fieldDef.type:'text';
      return `<label for="${id}">${label}<input id="${id}" data-os-id="${id}" type="${type}"${required}${max}></label>`;
    };
    for(const module of recordModules){
      const id=module.id,fieldsMarkup=module.fields.map(fieldDef=>genericControl(module,fieldDef)).join('');
      genericPanels[id]=`<section class="simple-app" id="panel-${id}" data-app-panel="${id}" hidden><div class="app-heading"><div><small>${curioidOsEscape(module.source||'CURIOID MODULE')} / PRIVATE DATA</small><h2>${curioidOsEscape(module.name)}</h2><p>${curioidOsEscape(module.description)}</p></div></div><div class="form-grid">${fieldsMarkup}</div><div class="app-actions"><button type="button" id="module-save-${id}" data-os-id="module-save-${id}" class="primary">Add ${curioidOsEscape(module.recordLabel||'entry')}</button><label class="module-index-label" for="module-index-${id}">Item #<input type="number" min="1" step="1" id="module-index-${id}" data-os-id="module-index-${id}" inputmode="numeric" placeholder="1"></label><button type="button" id="module-delete-${id}" data-os-id="module-delete-${id}">Delete selected</button></div><pre class="simple-list" id="module-list-${id}" data-os-id="module-list-${id}" aria-live="polite">Nothing here yet.</pre></section>`;
    }
