    const content=availableTools.map((tool,index)=>{const panel=panels[tool]||genericPanels[tool];return panel.replace(' hidden>',index===0?'>':' hidden>');}).join('')||`<section class="simple-empty"><div class="empty-mark">✳</div><h2>A blank world, ready for you.</h2><p>Return to Sandbox OS and add the pieces you want. Start with one module, or mix a whole workspace together.</p></section>`;
    const controls=`<div class="data-tools"><button type="button" id="data-export" data-os-id="data-export">↓ Export data</button><label class="restore-data" for="data-import">Restore data<input id="data-import" data-os-id="data-import" type="file" accept=".json,application/json"></label><button type="button" id="data-reload" data-os-id="data-reload">Reload saved data</button></div>`;
