  // One native fullscreen controller shared by every desktop-style OS.
  // The browser remains in charge of the fullscreen state (including Escape).
  function bindOsFullscreen(shell, button, onError = () => {}) {
    let alive = true;
    const getViewportHeight = () => Math.max(240, Math.round(window.visualViewport?.height || window.innerHeight || document.documentElement.clientHeight || 600));
    const sync = () => {
      if (!shell) return;
      const active = document.fullscreenElement === shell;
      shell.classList.toggle('curioid-os-fullscreen-active', active);
      if (active) shell.style.setProperty('--curioid-fullscreen-height', `${getViewportHeight()}px`);
      else shell.style.removeProperty('--curioid-fullscreen-height');
      if (button) {
        button.setAttribute('aria-pressed', String(active));
        button.setAttribute('aria-label', active ? 'Exit fullscreen' : 'Enter fullscreen');
        button.title = active ? 'Exit fullscreen' : 'Enter fullscreen';
      }
    };
    const onViewportResize = () => {
      if (!alive || document.fullscreenElement !== shell) return;
      shell.style.setProperty('--curioid-fullscreen-height', `${getViewportHeight()}px`);
      requestAnimationFrame(() => {
        if (alive && document.fullscreenElement === shell) shell.dispatchEvent(new Event('curioid:fullscreen-layout'));
      });
    };
    const toggle = async () => {
      if (!alive) return;
      try {
        if (!shell || typeof shell.requestFullscreen !== 'function') throw new Error('Fullscreen is not supported by this browser.');
        if (document.fullscreenElement === shell) {
          if (document.exitFullscreen) await document.exitFullscreen();
          else throw new Error('The browser cannot exit fullscreen from this page.');
        } else {
          if (document.fullscreenElement) {
            if (!document.exitFullscreen) throw new Error('The browser cannot switch fullscreen elements.');
            await document.exitFullscreen();
          }
          await shell.requestFullscreen();
        }
      } catch (error) {
        try { onError(error?.message || 'Fullscreen is unavailable in this browser.'); } catch (_) {}
      } finally { sync(); }
    };
    button?.addEventListener('click', toggle);
    document.addEventListener('fullscreenchange', sync);
    window.addEventListener('resize', onViewportResize, { passive: true });
    window.addEventListener('orientationchange', onViewportResize, { passive: true });
    window.visualViewport?.addEventListener('resize', onViewportResize, { passive: true });
    sync();
    return {
      toggle,
      sync,
      destroy() {
        if (!alive) return;
        alive = false;
        button?.removeEventListener('click', toggle);
        document.removeEventListener('fullscreenchange', sync);
        window.removeEventListener('resize', onViewportResize);
        window.removeEventListener('orientationchange', onViewportResize);
        window.visualViewport?.removeEventListener('resize', onViewportResize);
        shell?.classList.remove('curioid-os-fullscreen-active');
        shell?.style.removeProperty('--curioid-fullscreen-height');
        if (document.fullscreenElement === shell && document.exitFullscreen) { try { Promise.resolve(document.exitFullscreen()).catch(() => {}); } catch (_) {} }
      }
    };
  }

  // CURIOID Workshop: small, local-first services shared by independent experiences.
