      diagnosticsOutput.textContent = 'Running Kernel self-tests, registry integrity checks and cross-world compatibility analysis…';
      try {
        const result = await window.CurioidKernel?.runDiagnostics?.({ persistHistory: false });
        if (!result) throw new Error('The CURIOID Kernel diagnostics service is unavailable.');
        if (destroyed) return;
        latestDiagnostics = result;
        const summary = result.summary || {};
        const integrity = result.integrity?.summary || {};
        const selfTest = result.selfTest?.summary || {};
        const checks = Array.isArray(result.selfTest?.checks) ? result.selfTest.checks : [];
        const failures = checks.filter(item => item.status === 'fail');
        const warnings = (result.integrity?.issues || []).filter(item => item.severity === 'warning' || item.severity === 'error').slice(0, 8);
        const lines = [
          `RESULT: ${result.status || 'completed'}`,
          `KERNEL ${result.kernelVersion || 'unknown'} / CONNECT ${result.connectVersion || 'unknown'}`,
          `SELF-TESTS: ${selfTest.passed ?? 0} passed / ${selfTest.failed ?? failures.length} failed / ${selfTest.total ?? checks.length} total`,
          `INTEGRITY: ${integrity.errorCount ?? 0} errors / ${integrity.warningCount ?? 0} warnings / ${integrity.checksPassed ?? 0} checks passed`,
          `COMPATIBILITY: ${summary.declaredDependencies ?? 0} contracts / ${summary.unresolvedDependencies ?? 0} unresolved / ${summary.ambiguousDependencies ?? 0} ambiguous`,
          `ACTIVE ADAPTERS: ${window.CurioidKernel?.status?.().adapterCount ?? 0} / 6`,
          `DURATION: ${Number(result.durationMs || 0).toLocaleString()} ms`
        ];
        if (failures.length) lines.push('', 'FAILED SELF-TESTS:', ...failures.slice(0, 8).map(item => `- ${item.name || item.id}: ${item.message || item.detail || 'Check failed'}`));
        if (warnings.length) lines.push('', 'INTEGRITY ITEMS TO REVIEW:', ...warnings.map(item => `- ${item.severity}: ${item.title || item.code || item.message || 'Review required'}`));
        if (!failures.length && !warnings.length && result.status === 'healthy') lines.push('', 'No Kernel self-test failures or integrity warnings were reported.');
        lines.push('', 'Scope: shared Kernel, registry, adapters and declared contracts. Individual OS apps still need browser-level interaction testing.');
        diagnosticsOutput.textContent = lines.join('\n');
        if (diagnosticsSaveButton) diagnosticsSaveButton.disabled = false;
      } catch (error) {
        latestDiagnostics = null;
        diagnosticsOutput.textContent = `DIAGNOSTICS COULD NOT COMPLETE\n${error.message || String(error)}\nNo project data was changed.`;
      } finally {
        if (!destroyed && diagnosticsRunButton) diagnosticsRunButton.disabled = false;
      }
