      setSearchOpen(false); searchToggle.removeEventListener('click',onSearchToggle); searchInput.removeEventListener('input',onSearchInput); bellaButton.removeEventListener('click',onBellaSearch); searchDock.removeEventListener('click',onSearchDockClick); searchDock.removeEventListener('keydown',onSearchKey); document.removeEventListener('pointerdown',onSearchOutside,true); searchDock.remove();
