        'dead-interface': '.retro-taskbar', 'food-alchemy': '.food-os-taskbar', 'echonoise-os': '.eno-taskbar',
        'umbra-os': '.umbra-taskbar', 'aether-os': '.aether-statusbar', 'aura-synthesis': '.aura-taskbar'
