      const title = make('h4', '', item.name || 'Untitled item');
      const meta = make('small', 'exchange-item-meta', `${item.sourceOS || currentName} · ${new Date(item.createdAt || Date.now()).toLocaleString()}${item.kernelArtifactId ? ' · KERNEL ROUTED' : ''}`);
      if (item.kernelArtifactId) meta.title = `Kernel artifact ${item.kernelArtifactId}`;
      const summary = make('p', 'exchange-item-summary', itemSummary(item));
      const actions = make('div', 'exchange-item-actions');
      const actionButton = (label, action, style = '') => { const button = make('button', style, label); button.type = 'button'; button.dataset.exAction = action; button.dataset.exId = item.id; return button; };
