        const request = tx.objectStore('items').getAll();
        let value = [];
        request.onsuccess = () => { value = request.result || []; };
        tx.oncomplete = () => { db.close(); resolve(value); };
        tx.onerror = () => { db.close(); reject(tx.error || new Error('Could not read Exchange storage.')); };
