        <div class="project-utility-actions">
          <button type="button" class="project-utility-button" data-project-randomize title="Randomize adjustable controls">Surprise me</button>
          <button type="button" class="project-utility-button" data-project-export>Export preset</button>
          <label class="project-utility-button project-utility-import">Import preset<input type="file" data-project-import accept="application/json,.json" aria-label="Import project preset"></label>
          <button type="button" class="project-utility-button" data-project-snapshot>Save snapshot</button>
          <button type="button" class="project-utility-button" data-project-focus aria-pressed="false">Focus view</button>
          <button type="button" class="project-utility-button" data-project-reset>Reset controls</button>
        </div>
      </div>
