      const c=target.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.fillStyle='#080b14';c.fillRect(0,0,w,h);
      const src=image||sample,mode=$('[data-select="image-mode"]',root).value,count=+$('[data-range="echo-count"]',root).value,strength=+$('[data-range="echo-strength"]',root).value/100,off=+$('[data-range="offset"]',root).value/100,sep=+$('[data-range="separation"]',root).value/100,tears=+$('[data-range="afterimage-tears"]',root).value/100,scan=+$('[data-range="afterimage-scan"]',root).value/100,grain=+$('[data-range="image-grain"]',root).value/100;
      const scale=Math.min((w*.83)/src.width,(h*.82)/src.height),iw=src.width*scale,ih=src.height*scale,x=(w-iw)/2,y=(h-ih)/2;
      const filters={memory:'saturate(.8) contrast(1.25)',misregister:'contrast(1.8) saturate(2.2)',cold:'hue-rotate(190deg) saturate(1.8) contrast(1.5)',heat:'sepia(.7) saturate(2.3) contrast(1.4)',negative:'invert(1) contrast(1.4)',xerox:'grayscale(1) contrast(3.8)',spectral:'saturate(2.8) contrast(1.7)',liquid:'hue-rotate(70deg) saturate(2.2) contrast(1.35)',signal:'invert(.82) hue-rotate(130deg) saturate(2.4)',ghost:'grayscale(.3) contrast(1.8)'};
      c.save();c.shadowColor='#000';c.shadowBlur=24;c.globalAlpha=.5;c.fillStyle='#03040a';c.fillRect(x-15,y-15,iw+30,ih+30);c.restore();
