    function getRoomName(room){const names=doorsExpertMode?{reception:'Desktop',workshop:'Documents',records:'My Files','image-studio':'Pictures',observatory:'System Tools',signals:'Network',arcade:'Games',service:'Control Panel',annex:'Accessories',unnumbered:'Other'}:{reception:'Reception',workshop:'Workshop',records:'Records','image-studio':'Image Studio',observatory:'Observatory',signals:'Signal Exchange',arcade:'Arcade',service:'Service Wing',annex:'Oddities Annex',unnumbered:'Room 00'};return names[room]||userRooms.find(r=>r.id===room)?.name||(doorsExpertMode?'My Files':'Records');}
    function saveTextToDrive(name,content,room='workshop',existingId=null,mime='text/plain',deferPersist=false){if(deferPersist!==true)throw new Error('C: direct text staging is internal. Use saveTextToDriveVerified() so persistence is awaited and verified.');const filename=String(name||'UNTITLED.TXT').trim().replace(/[\\/:*?"<>|]/g,'-').slice(0,100)||'UNTITLED.TXT';let file=existingId?virtualFiles.find(f=>f.id===existingId):null;if(!file){file={id:newDoors98KeyId(),name:filename,room,folder:room,type:mime==='text/csv'?'csv':'text',mime,content:'',size:0,updated:new Date().toISOString(),userCreated:true};virtualFiles.unshift(file);}if(driveBlobs.has(file.id))driveBlobs.delete(file.id);file.blob=null;file.name=filename;file.room=room;file.folder=room;file.content=String(content??'');file.type=mime==='text/csv'?'csv':'text';file.mime=mime;file.size=new Blob([file.content]).size;file.updated=new Date().toISOString();return file;}
