            ring:[{transform:'rotate(0)'},{transform:'rotate(-10deg) translateY(-2px)',offset:.2},{transform:'rotate(9deg) translateY(-3px)',offset:.42},{transform:'rotate(-6deg)',offset:.65},{transform:'rotate(3deg)',offset:.82},{transform:'rotate(0)'}],
