      function bellaSetMood(mood='pleasant',duration=0){if(!bellaCharacter)return;clearTimeout(bellaMoodTimer);bellaCharacter.classList.remove('bella-mood-angry','bella-mood-sad','bella-mood-uncanny','bella-mood-concerned');if(['angry','sad','uncanny','concerned'].includes(mood)){bellaCharacter.classList.add(`bella-mood-${mood}`);if(mood==='angry')bellaAnimate('wiggle',900);else if(mood==='sad')bellaAnimate('dozy',1400);else if(mood==='uncanny')bellaAnimate('peek',1100);else bellaAnimate('curious',1100);}if(duration>0)bellaMoodTimer=setTimeout(()=>bellaCharacter?.classList.remove(`bella-mood-${mood}`),duration);}
