      const pairFamilies=families.join('+');let name='',summary='',method='',kind='dish',rarity='uncommon';
      const familyName=(item)=>item.name.toLowerCase();
      const protein=[a,b].find(x=>familyOf(x)==='protein');
      const produce=[a,b].find(x=>familyOf(x)==='produce');
      const fruit=[a,b].find(x=>familyOf(x)==='fruit');
      const grain=[a,b].find(x=>familyOf(x)==='grain');
      const legume=[a,b].find(x=>familyOf(x)==='legume');
      const dairy=[a,b].find(x=>familyOf(x)==='dairy');
      const spice=[a,b].find(x=>familyOf(x)==='spice');
      const pantry=[a,b].find(x=>familyOf(x)==='pantry');
      const heat=ids.has('heat');
      if(has('miso','honey')||has('miso','maple-syrup')){name='Miso-sweet glaze';summary='A glossy sweet-savoury glaze with fermented depth, useful on roasted vegetables, tofu or salmon.';method='Whisk miso with a little honey or maple syrup and warm water until brushable. Taste before adding salt; use as a finishing glaze.';kind='component';}
      else if(has('soy','honey')){name='Honey-soy finishing glaze';summary='A quick glossy glaze balancing salt, sweetness and deep savoury notes.';method='Stir soy sauce with honey and a splash of water. Simmer briefly until lightly syrupy, then brush onto cooked vegetables, tofu or thoroughly cooked protein.';kind='component';}
      else if(has('peanut-butter','soy')){name='Peanut-soy noodle sauce';summary='A creamy, salty and nutty sauce that works especially well with noodles or roasted vegetables.';method='Whisk peanut butter with soy sauce and warm water. Add a little lime or vinegar if available, then loosen to a pourable consistency.';kind='component';}
      else if(has('chocolate','chilli')){name='Chilli-dark chocolate sauce';summary='A bittersweet chocolate sauce with a restrained warm chilli finish. The contrast is intentional, not a mistake.';method='Melt dark chocolate gently with a small amount of cream or water. Add a tiny pinch of chilli, taste, and increase gradually. Serve with fruit or a simple dessert.';kind='component';rarity='rare';}
      else if(has('yogurt','mint')||has('yogurt','garlic')||has('yogurt','dill')){name='Herbed yogurt dip';summary='A cool tangy dip with fresh herbal lift, suitable for vegetables, flatbread or grilled dishes.';method='Stir the herbs or finely grated garlic into yogurt. Add a little salt and lemon if available, then chill briefly.';kind='component';}
      else if(has('tahini','lemon')){name='Lemon tahini dressing';summary='A nutty, tangy dressing that becomes creamy when tahini is whisked with citrus and water.';method='Whisk tahini with lemon juice, then add cold water a little at a time until pale and pourable. Season lightly.';kind='component';}
      else if(heat&&protein){name=`${familyName(protein)} with simple ${familyName(protein)==='fish'?'pan':'roasted'} finish`;summary=`A straightforward cooked ${familyName(protein)} concept. The heat step changes the texture and makes it a finished preparation.`;method='Season to suit the ingredient, then cook using a suitable method until safely cooked through. Follow reliable food-safety guidance for the ingredient and thickness; rest briefly before serving.';}
      else if(heat&&produce){name=`Roasted ${familyName(produce)}`;summary=`A simple roasted ${familyName(produce)} preparation that concentrates its natural sweetness and savoury edges.`;method='Cut into even pieces, coat lightly with oil if available, season, and roast until tender with browned edges. Cooking time depends on the cut size and oven.';}
