      while(changed){changed=false;for(const [candidate,item] of Object.entries(state.items)){if(remove.has(candidate)||baseItems[candidate])continue;if(Array.isArray(item.recipeInputs)&&item.recipeInputs.some(input=>remove.has(input))){remove.add(candidate);changed=true;}}}
