      const batch={id:`trash-${uid()}-${Date.now().toString(36)}`,removedAt:Date.now(),items:[...remove].map(key=>({id:key,item:{...(getItem(key)||{id:key,name:key})},known:state.known.includes(key),custom:state.custom.includes(key),pinned:state.pinned.includes(key),workspace:state.workspace.includes(key),base:Boolean(baseItems[key])})),pairs:Object.entries(state.pairs).filter(([pair,result])=>remove.has(result)||pair.split('::').some(key=>remove.has(key))),log:state.log.filter(entry=>remove.has(entry.a)||remove.has(entry.b)||remove.has(entry.result))};
