      const trialIds=isDish?sourceIdsForItem(saved||recipe).filter(id=>getItem(id)&&getItem(id).kind!=='tool'):[];
      const familyCounts=trialIds.reduce((map,id)=>{const family=familyOf(getItem(id));map[family]=(map[family]||0)+1;return map;},{});
