      if(songBookReadOnly||!Array.isArray(nextSongs)||nextSongs.length>80){setFeedback(songBookReadOnly?'The Songbook is in read-only recovery mode. Existing saved sessions were preserved.':'The Songbook is limited to 80 sessions. Export the archive and remove an old session before saving.');return false;}
      let serialized;try{serialized=JSON.stringify(nextSongs.map(sanitizeSong));}catch(error){setFeedback(`The Songbook could not be prepared: ${error?.message||'invalid session data'}.`);return false;}
