      $$e('[data-eno-step]').forEach(b=>{const on=Boolean(state.pattern[+b.dataset.enoTrack][+b.dataset.enoStep]);b.classList.toggle('is-on',on);b.setAttribute('aria-pressed',String(on));});
      $$e('[data-eno-voice-toggle]').forEach(b=>{const on=Boolean(state.voices[+b.dataset.enoVoiceToggle]);b.classList.toggle('is-enabled',on);b.setAttribute('aria-pressed',String(on));const s=b.querySelector('i');if(s)s.textContent=on?'ON':'OFF';});
