      const tempo=Math.round(60000000/state.bpm),header=[77,84,104,100,0,0,0,6,0,1,0,2,0,120],tempoEvents=[{t:0,order:0,data:[255,81,3,(tempo>>16)&255,(tempo>>8)&255,tempo&255]},{t:0,order:1,data:[255,3,6,...Array.from('Tempo ').map(c=>c.charCodeAt(0))]}];
