      if(name==='clear-piano'){state.pianoNotes=[];if(!persist())return;renderPianoRoll($e('[data-eno-window=\"piano\"]'));setFeedback('Piano Roll melody cleared.');return;}
      if(name==='arr-add-bar'){if(state.arrangement.length>=16){setFeedback('Arrangement is limited to 16 bars in this version.');return;}state.arrangement.push(state.arrangement[state.arrangement.length-1]||'A');if(!persist())return;renderArrangement($e('[data-eno-window=\"arrangement\"]'));setFeedback('Added one arrangement bar.');return;}
      if(name==='arr-remove-bar'){if(state.arrangement.length<=1){setFeedback('An arrangement needs at least one bar.');return;}state.arrangement.pop();if(!persist())return;renderArrangement($e('[data-eno-window=\"arrangement\"]'));setFeedback('Removed the last arrangement bar.');return;}
