      if(name==='play-choir')playChoir();if(name==='stop-choir'){stopChoir();setFeedback('Choir silenced.');}if(name==='random-voices')randomVoices();if(name==='generate-vocal')generateVocal();if(name==='sing-vocal')singVocal();if(name==='export-phonemes')exportPhonemeSheet();if(name==='export-vocal-midi')exportVocalMidi();if(name==='save-aliases'){const field=$e('[data-eno-alias-overrides]');state.vocalAliasOverrides=clean(field?.value||'',6000);if(!persist())return;setFeedback('Voicebank alias map saved.');}if(name==='clear-voicebank'){voicebank.name='';voicebank.files.clear();voicebank.aliases.clear();voicebank.buffers.clear();voicebank.stats={files:0,aliases:0,loaded:0};paintVoicebankStatus();setFeedback('Voicebank unloaded.');}if(name==='export-aliases')downloadJSON(parseCustomLines(state.vocalAliasOverrides),'echonoise-voicebank-alias-map.json');
      if(name==='fx-preset'){state.fx={echo:52,feedback:44,harmonics:71,filter:62,glitch:23,drive:18,stereo:88,decay:60};if(!persist())return;syncUI();applyFx();}
      if(name==='mix-reset'){state.levels=[.72,.62,.78,.62,.58];state.pan=enoVoices.map(v=>v.pan);if(!persist())return;}if(name==='solo-lead'){state.levels=[0,0,.9,0,0];if(!persist())return;}syncUI();
      if(name==='save-song'){const win=$e('[data-eno-window="songbook"]');if(songs.length>=80){setFeedback('The Songbook is full (80 sessions). Export it and delete an older session before saving another.');return;}const songName=win?.querySelector('[data-eno-song-name]')?.value||'Untitled transmission',song=captureSong(songName),nextSongs=[...songs,song];if(!saveBook(nextSongs)){setFeedback('Could not save the Songbook. Existing saved sessions were preserved.');return;}songs=nextSongs;renderSongList(win);setFeedback(`SAVED / ${song.name}`);}
