      if(name==='export-songbook-recovery'){if(!songBookReadOnly||typeof songBookRawSnapshot!=='string'){setFeedback('The original Songbook bytes are not currently readable. Restore browser storage access before exporting.');return;}exportBlob(new Blob([songBookRawSnapshot],{type:'application/json'}),'echonoise-songbook-recovery.raw.json');setFeedback('Exact original Songbook storage text exported. Keep this recovery copy safe.');}
