    async function handleLexiconAction(action,win){
      const status=win?.querySelector('[data-eno-lex-feedback]');
      const sayLex=(message)=>{if(status)status.textContent=message;};
      try{
        sayLex('Loading the local pronunciation dictionary…');
        const dict=await ensurePronunciationDictionary();
        const statusPill=win?.querySelector('[data-eno-lexicon-status]');if(statusPill)statusPill.textContent=`${Object.keys(dict).length.toLocaleString()} pronunciations ready`;
        if(action==='lookup'){runLexiconLookup(win,win.querySelector('[data-eno-lex-word]')?.value,dict);sayLex('Dictionary lookup complete. Estimated pronunciations are clearly marked.');}
        else if(action==='rhyme'){runLexiconRhymes(win,win.querySelector('[data-eno-lex-rhyme]')?.value,dict);sayLex('Exact rhymes are matched by ARPABET sound, not spelling.');}
        else if(action==='scan'){const study=runLexiconScan(win,win.querySelector('[data-eno-lex-meter-text]')?.value,dict);sayLex(study?`Scanned ${study.lines.length} line(s) · ${study.words.length} word entries. Estimated words are marked.`:'No lyric lines to scan.');}
        else if(action==='sounds'){const study=runLexiconSounds(win,win.querySelector('[data-eno-lex-sounds-text]')?.value,dict);sayLex(study?`Sound palette analysed · ${study.words.length} words · ${study.sounds.alliteration.length} alliteration · ${study.sounds.assonance.length} assonance · ${study.sounds.consonance.length} consonance groups.`:'No text to analyse.');}
        else if(action==='phonemes'){const study=runLexiconPhonemeSearch(win,win.querySelector('[data-eno-lex-phonemes]')?.value,dict);sayLex(study?`Found ${study.search.total} pronunciation match(es) for ${study.search.query}. Save or export this search as a phonetic study.`:'Enter a valid phoneme sequence.');}
        else if(action==='similar'){runLexiconSimilar(win,win.querySelector('[data-eno-lex-similar]')?.value,dict);sayLex('Sound neighbours calculated from the local pronunciation dictionary and personal pronunciations.');}
        else if(action==='meterwords'){const study=runLexiconMeterWords(win,win.querySelector('[data-eno-lex-meterword-pattern]')?.value,dict);sayLex(study?`Found ${study.search.total} word(s) with that stress contour.`:'Enter a stress contour to search.');}
        else if(action==='compare'){const study=runLexiconCompare(win,win.querySelector('[data-eno-lex-compare-a]')?.value,win.querySelector('[data-eno-lex-compare-b]')?.value,dict);sayLex(study?'Phonetic comparison complete. Save it to your notebook or use both words in Vocal Synth.':'Enter two words to compare.');}
        else if(action==='palette'){const palette=runLexiconPalette(win,win.querySelector('[data-eno-lex-palette-text]')?.value,dict);sayLex(palette?'Sound palette generated locally. Open UMBRA or save it as a Kernel artifact to share the colors.':'Enter a phrase to generate a palette.');}
        else if(action==='publish-palette'){if(!lastLexiconPalette)throw new Error('Generate a sound palette first.');const artifact=await CurioidKernel.createArtifact({sourceExperienceId:'echonoise-os',type:'echonoise/sound-palette',title:`Sound palette · ${String(lastLexiconPalette.phrase||'').slice(0,48)}`,data:lastLexiconPalette,metadata:{generator:'echonoise.lexicon',seed:lastLexiconPalette.seed,colors:lastLexiconPalette.colors.length}});sayLex(`Created local Kernel artifact ${artifact.id}. Open UMBRA or another receiving OS and import it through Exchange.`);}
        else if(action==='save-dictionary'){const field=win.querySelector('[data-eno-lex-custom-lines]'),parsed=parseCustomPronunciationVariants(field?.value||'');if(!parsed.size)throw new Error('No valid pronunciation entries found. Use word = AH0 L OW1.');state.vocalPronunciationOverrides=clean(field.value,280000);if(!persist())return;phoneticEntries=null;phoneticRhymeIndex=null;phoneticIndexOverrideSignature='';customPronunciationMap=null;customPronunciationSource=null;const out=win.querySelector('[data-eno-lex-dictionary-result]');if(out)out.textContent=`Saved ${parsed.size} custom word entr${parsed.size===1?'y':'ies'} locally. Up to four pronunciations per word are supported.`;sayLex(`Saved ${parsed.size} custom pronunciations.`);}
        else if(action==='export-dictionary'){downloadJSON({format:'echonoise-pronunciation-overrides',version:1,entries:state.vocalPronunciationOverrides},'echonoise-personal-pronunciations.json');sayLex('Personal pronunciations exported.');}
        else if(action==='import-dictionary'){win.querySelector('[data-eno-lex-dictionary-file]')?.click();return;}
        else if(action==='reset-dictionary'){if(!window.confirm('Remove all personal pronunciation overrides from this browser?'))return;state.vocalPronunciationOverrides='';if(!persist())return;phoneticEntries=null;phoneticRhymeIndex=null;phoneticIndexOverrideSignature='';const field=win.querySelector('[data-eno-lex-custom-lines]');if(field)field.value='';const out=win.querySelector('[data-eno-lex-dictionary-result]');if(out)out.textContent='Personal pronunciation overrides cleared. The original dictionary is unchanged.';sayLex('Custom pronunciations cleared.');}
        else if(action==='save'){if(!lastLexiconStudy){const text=win.querySelector('[data-eno-lex-meter-text]')?.value||state.lyrics;runLexiconScan(win,text,dict);}const saved=saveLexiconStudy();renderLexiconStudies(win);sayLex(`Saved “${saved.title}” to your local phonetic notebook.`);}
        else if(action==='export'){const data=lastLexiconStudy||lexiconStudies[lexiconStudies.length-1];if(!data)throw new Error('Run or save a study before exporting.');downloadJSON(data,`${(data.title||'echonoise-lyric-study').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'echonoise-lyric-study'}.echostudy.json`);sayLex('Study exported as a portable JSON file.');}
      }catch(error){sayLex(error.message||'Lexicon analysis failed.');}
    }
    // The Lexicon remains an Echonoise-owned service, but its structured,
    // read-only analysis API can be called by any registered Kernel experience.
    const lexiconServiceId='echonoise.lexicon.analyze';
    window.CurioidLexicon=Object.freeze({
      version:'3.0.0',source:'ECHONOISE_ARPA',dictionaryEntries:()=>Object.keys(window.ECHONOISE_ARPA||{}).length,
      async lookup(word){const dict=await ensurePronunciationDictionary(),details=lexiconWordDetails(word,dict);return details?{...details,syllables:details.syllables.map(item=>({...item}))}:null;},
      async analyze(text){const dict=await ensurePronunciationDictionary(),phrase=clean(text,1800),sounds=analyzeLexiconSounds(phrase,dict),lines=phrase.split(/\r?\n/).slice(0,24).filter(Boolean).map(line=>{const syllables=phonemizeLyrics(line,dict);return{text:line,syllableCount:syllables.length,stress:syllables.map(item=>item.stress===1?'/':item.stress===2?'\\':'×').join(' '),phones:syllables.map(item=>item.phones.join(' ')).join(' | '),estimated:syllables.filter(item=>item.estimated).length};});return{format:'curioid-phonetic-analysis',version:2,source:'echonoise.lexicon',createdAt:new Date().toISOString(),phrase,lines,words:sounds.words.slice(0,100).map(item=>({word:item.word,phones:item.phones,ipa:item.ipa,syllables:item.syllables.length,stress:item.stress,known:item.known,pronunciationSource:item.pronunciationSource,estimated:item.estimated,rhymeKey:item.rhymeKey})),sounds:{alliteration:sounds.alliteration,assonance:sounds.assonance,consonance:sounds.consonance},fingerprint:buildLexiconFingerprint(phrase,dict)};},
      async rhymes(word,limit=80){const dict=await ensurePronunciationDictionary(),details=lexiconWordDetails(word,dict);if(!details)return[];const key=details.rhymeKey;return getPhoneticRhymeIndex(dict).get(key)?.filter(item=>item!==details.word).slice(0,clamp(Number(limit)||80,1,160))||[];},
      async compare(wordA,wordB){const dict=await ensurePronunciationDictionary(),a=lexiconWordDetails(wordA,dict),b=lexiconWordDetails(wordB,dict);if(!a||!b)throw new Error('Two English words are required.');return{format:'curioid-phonetic-comparison',version:1,a,b,alignment:alignLexiconPhones(a.phones,b.phones)};},
      async palette(text){const dict=await ensurePronunciationDictionary();return buildLexiconSoundPalette(clean(text,1800),dict);},
      async findStress(pattern,limit=60){const dict=await ensurePronunciationDictionary(),symbols=String(pattern||'').replace(/[|,]+/g,' ').trim().split(/\s+/).filter(Boolean).flatMap(token=>[...token]).map(char=>char==='.'?'×':char);if(!symbols.length||symbols.length>12||symbols.some(char=>!['/','\\','×'].includes(char)))throw new Error('Use /, \\ and × stress symbols.');const results=[];for(const[word,phones]of getLexiconPronunciationEntries(dict)){const syllables=phonesToSyllables(word,phones,0),test=syllables.map(item=>item.stress===1?'/':item.stress===2?'\\':'×');if(test.length===symbols.length&&test.every((value,index)=>value===symbols[index])&&!results.includes(word))results.push(word);if(results.length>=Math.min(200,Math.max(1,Number(limit)||60)))break;}return results;},
      async fingerprint(text){const dict=await ensurePronunciationDictionary();return buildLexiconFingerprint(clean(text,1800),dict);},
      async findPhonemes(pattern,mode='whole',limit=80){const dict=await ensurePronunciationDictionary(),tokens=String(pattern||'').trim().toUpperCase().split(/\s+/).filter(Boolean);if(!tokens.length||tokens.length>24||tokens.some(phone=>phone!=='*'&&!validArpabetPhone(phone)))throw new Error('Use 1–24 valid ARPABET phonemes or * wildcards.');const strategy=['whole','start','end','any'].includes(mode)?mode:'whole',results=new Map();for(const[word,phones]of getLexiconPronunciationEntries(dict)){let found=false;const matches=(query,actual)=>query==='*'||(normalizePhone(actual)===normalizePhone(query)&&(!/[012]$/.test(query)||String(actual).toUpperCase()===query));if(strategy==='whole')found=phones.length===tokens.length&&tokens.every((q,i)=>matches(q,phones[i]));else if(strategy==='start')found=phones.length>=tokens.length&&tokens.every((q,i)=>matches(q,phones[i]));else if(strategy==='end'){const offset=phones.length-tokens.length;found=offset>=0&&tokens.every((q,i)=>matches(q,phones[offset+i]));}else for(let i=0;i<=phones.length-tokens.length&&!found;i++)found=tokens.every((q,j)=>matches(q,phones[i+j]));if(found&&!results.has(word)){const details=lexiconWordDetails(word,dict);results.set(word,{word,phones,ipa:arpabetToIPA(phones),syllables:details.syllables.length,stress:details.stress,known:details.known,pronunciationSource:details.pronunciationSource});}if(results.size>=Math.min(200,Math.max(1,Number(limit)||80)))break;}return{format:'curioid-phoneme-search',version:1,query:tokens.join(' '),mode:strategy,total:results.size,results:[...results.values()]};},
    });
    CurioidKernel.registerCapability({id:lexiconServiceId,ownerExperienceId:'echonoise-os',name:'Phonetic text analysis',version:'3.0.0',description:'Analyze text into ARPABET, broad IPA, syllable stress, alliteration, assonance, consonance and phonetic fingerprints using Echonoise local pronunciation data.',access:'public',inputSchema:{text:'English text, up to 1,800 characters'},outputSchema:{format:'curioid-phonetic-analysis',version:2},inputContract:{type:'object',required:['text'],properties:{text:{type:'string',maxLength:1800}},additionalProperties:false},outputContract:{type:'object'},handler:input=>window.CurioidLexicon.analyze(input?.text||'')});
