    CurioidKernel.registerCapability({id:'echonoise.lexicon.compare',ownerExperienceId:'echonoise-os',name:'Pronunciation comparison',version:'3.0.0',description:'Compare two words with phoneme alignment, edit distance, similarity and syllable stress details.',access:'public',inputSchema:{wordA:'First word',wordB:'Second word'},outputSchema:{format:'curioid-phonetic-comparison',version:1},inputContract:{type:'object',required:['wordA','wordB'],properties:{wordA:{type:'string',minLength:1,maxLength:80},wordB:{type:'string',minLength:1,maxLength:80}},additionalProperties:false},outputContract:{type:'object'},handler:input=>window.CurioidLexicon.compare(input?.wordA||'',input?.wordB||'')});
