        <nav class="umbra-menubar" aria-label="Editor menu"><button type="button" data-u-action="new">File</button><button type="button" data-u-launch="history">Edit</button><button type="button" data-u-launch="filters">Image</button><button type="button" data-u-launch="layers">Layer</button><button type="button" data-u-launch="selection">Select</button><button type="button" data-u-launch="filters">Filter</button><button type="button" data-u-launch="color">Colors</button><button type="button" data-u-launch="export">Export</button></nav>
