    function makeSnapshot(label){const data=serialize(),bytes=data.layers.reduce((n,l)=>n+(l.canvas?.length||0)+(l.mask?.length||0),0);return{label,data,bytes};}
    function trimSnapshots(stack){let total=stack.reduce((n,item)=>n+(item.bytes||0),0);while(stack.length>1&&(stack.length>HISTORY_LIMIT||total>HISTORY_BYTE_LIMIT)){total-=stack.shift().bytes||0;}}
