      const scale=clamp(Number(q('[data-u-transform-scale]').value)||100,10,300)/100,rotation=clamp(Number(q('[data-u-transform-rotation]').value)||0,-180,180)*Math.PI/180,dx=clamp(Number(q('[data-u-transform-x]').value)||0,-4096,4096),dy=clamp(Number(q('[data-u-transform-y]').value)||0,-4096,4096),flipX=q('[data-u-transform-flip-x]').checked,flipY=q('[data-u-transform-flip-y]').checked;
