      const apply=source=>{const out=makeCanvas(),c=out.getContext('2d');c.translate(doc.width/2+dx,doc.height/2+dy);c.rotate(rotation);c.scale(scale*(flipX?-1:1),scale*(flipY?-1:1));c.drawImage(source,-doc.width/2,-doc.height/2);return out;};
