    function pasteSelection(){if(!selectionClipboard){note('The UMBRA clipboard is empty. Copy or cut a selection first.');return;}checkpoint('Paste selection');const layer=createLayer('Pasted pixels');if(!layer)return;layer.canvas.getContext('2d').drawImage(selectionClipboard.canvas,selectionClipboard.x,selectionClipboard.y);selection={x:selectionClipboard.x,y:selectionClipboard.y,w:selectionClipboard.w,h:selectionClipboard.h};drawSelectionOverlay();markChanged('Pasted pixels on a new layer');}
    function deleteSelection(){if(!selection){note('Create a marquee selection first.');return;}const l=current();if(!l||l.locked){note('Unlock a layer before deleting pixels.');return;}checkpoint(maskMode?'Hide selected pixels with the layer mask':'Delete selected pixels');const target=maskMode&&l.mask?l.mask:l.canvas;target.getContext('2d').clearRect(selection.x,selection.y,selection.w,selection.h);markChanged(maskMode?'Selected area hidden by the layer mask':'Deleted selected pixels');}
    function clearSelection(){selection=null;pctx.clearRect(0,0,doc.width,doc.height);note('Selection cleared.');}
    function selectAll(){selection={x:0,y:0,w:doc.width,h:doc.height};drawSelectionOverlay();note('Entire canvas selected.');}
    function flipSelectedPixels(axis){if(!selection){note('Make a marquee selection first to flip selected pixels.');return;}const layer=current();if(!layer||layer.locked){note('Unlock the active layer before transforming pixels.');return;}const r=selection,w=Math.max(1,Math.floor(r.w)),h=Math.max(1,Math.floor(r.h));checkpoint('Flip selected pixels');for(const surface of [layer.canvas,layer.mask].filter(Boolean)){const c=surface.getContext('2d'),tmp=makeCanvas(w,h),tc=tmp.getContext('2d');tc.translate(axis==='horizontal'?w:0,axis==='vertical'?h:0);tc.scale(axis==='horizontal'?-1:1,axis==='vertical'?-1:1);tc.drawImage(surface,r.x,r.y,r.w,r.h,0,0,w,h);c.clearRect(r.x,r.y,r.w,r.h);c.drawImage(tmp,r.x,r.y);}if(layer.textInfo)layer.textInfo=null;markChanged(`Flipped selection ${axis}.`);}
    function transformDocument(mode){checkpoint(mode.replaceAll('-',' ')+' canvas');const oldW=doc.width,oldH=doc.height,newW=mode.startsWith('rotate')?oldH:oldW,newH=mode.startsWith('rotate')?oldW:oldH;const apply=source=>{const out=document.createElement('canvas');out.width=newW;out.height=newH;const c=out.getContext('2d');if(mode==='rotate-right'){c.translate(oldH,0);c.rotate(Math.PI/2);}else if(mode==='rotate-left'){c.translate(0,oldW);c.rotate(-Math.PI/2);}else if(mode==='flip-horizontal'){c.translate(oldW,0);c.scale(-1,1);}else if(mode==='flip-vertical'){c.translate(0,oldH);c.scale(1,-1);}c.drawImage(source,0,0);return out;};for(const layer of layers){layer.canvas=apply(layer.canvas);if(layer.mask)layer.mask=apply(layer.mask);if(layer.textInfo)layer.textInfo=null;}doc.width=newW;doc.height=newH;canvas.width=preview.width=composite.width=newW;canvas.height=preview.height=composite.height=newH;maskScratch.clear();selection=null;fitMode=true;fitZoom();syncUI();markChanged(`Canvas ${mode.replaceAll('-',' ')}.`);}
    function cloneStampAt(point){if(!drawing||!cloneSnapshot||!cloneSource)return;const ctx=drawing.layer.canvas.getContext('2d');ctx.save();if(selection)clipSelection(ctx);ctx.beginPath();ctx.arc(point.x,point.y,Math.max(1,brushSize/2),0,Math.PI*2);ctx.clip();ctx.globalAlpha=brushOpacity;ctx.drawImage(cloneSnapshot,drawing.from.x-cloneSource.x,drawing.from.y-cloneSource.y);ctx.restore();}

    function deleteLayer(){const i=layers.findIndex(l=>l.id===activeLayerId);if(i<0){note('Select a layer before deleting it.');return;}const active=layers[i];if(!window.confirm(`Delete “${active.name||'this layer'}”? You can undo this action.`))return;checkpoint('Delete layer');if(layers.length<=1){getCtx(current()).clearRect(0,0,doc.width,doc.height);if(current()?.mask)getCtx({canvas:current().mask}).clearRect(0,0,doc.width,doc.height);hasArtwork=false;markChanged('Cleared the only layer');return;}maskScratch.delete(active.id);layers.splice(i,1);activeLayerId=layers[Math.max(0,i-1)].id;updateLayerList();markChanged(`Deleted ${active.name||'layer'}`);}
