    function uaShowCongratulations(message){if(!uaPanel)return;let layer=uaPanel.querySelector('[data-ua-congratulations]');if(!layer){layer=document.createElement('section');layer.className='ua-congratulations';layer.dataset.uaCongratulations='';layer.hidden=true;layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');layer.setAttribute('aria-labelledby','ua-congratulations-title');const card=document.createElement('div'),eyebrow=document.createElement('small'),title=document.createElement('h3'),copy=document.createElement('p'),button=document.createElement('button');eyebrow.textContent='UMBRA ARCADE / ROUND COMPLETE';title.id='ua-congratulations-title';title.textContent='CONGRATULATIONS!';copy.dataset.uaCongratulationsCopy='';button.type='button';button.textContent='OK';card.append(eyebrow,title,copy,button);layer.append(card);if(getComputedStyle(uaPanel).position==='static')uaPanel.style.position='relative';uaPanel.append(layer);button.addEventListener('click',()=>{layer.hidden=true;uaRetry();uaCanvas?.focus?.();});}layer.querySelector('[data-ua-congratulations-copy]').textContent=String(message||'You completed the challenge.').slice(0,260);layer.hidden=false;layer.querySelector('button').focus();}
