    function uaFinishOne(completed){const ref=uaOnePoints,draw=uaPath;if(!draw.length){uaPhase='done';uaEl('[data-ua-timer]').textContent='0.0s';uaSay('Time is up. Start another round and chase the checkpoints.');uaUpdateUi();return;}const sample=uaResample(draw,80),errors=sample.map(p=>uaDistanceToPolyline(p,ref)),mean=errors.reduce((a,b)=>a+b,0)/errors.length,ratio=uaLength(draw)/Math.max(1,uaLength(ref));const accuracy=uaClamp(100-mean*.22-Math.abs(1-ratio)*22,0,100),progress=uaOneProgress/Math.max(1,ref.length),time=uaClamp((uaDeadline-performance.now())/18000,0,1),score=completed?uaClamp(accuracy*(.75+.25*progress)+time*8,0,100):Math.min(59,accuracy*progress*.62);uaPhase='done';uaSaveBest(score,completed);uaSay(completed?'All checkpoints cleared. Speed and accuracy combined into your score.':'Time up or route incomplete. Try again and hit the checkpoints in order.');uaUpdateUi();}
    function uaScoreMemory(){if(uaPath.length<12){uaPhase='done';uaSaveBest(0);uaSay('Too little of the glyph was redrawn. Give it another shot.');return;}const a=uaResample(uaPath,60),b=uaResample(uaTarget,60),ab=a.reduce((s,p)=>s+uaNearestDistance(p,b),0)/a.length,ba=b.reduce((s,p)=>s+uaNearestDistance(p,a),0)/b.length,mean=(ab+ba)/2,score=uaClamp(100-mean*.28-Math.abs(uaLength(uaPath)-uaLength(uaTarget))/Math.max(1,uaLength(uaTarget))*14,0,100);uaPhase='done';uaSaveBest(score,score>=85);uaSay(`Average path mismatch: ${mean.toFixed(1)} px. ${score>=85?'Your visual memory is sharp.':'That brain cache needs a refresh.'}`);}
    function uaScoreMirror(){if(uaPath.length<8){uaPhase='done';uaSaveBest(0);uaSay('Draw a little more of the missing side first.');return;}const a=uaResample(uaPath,60),b=uaResample(uaMirrorTarget,60),ab=a.reduce((s,p)=>s+uaNearestDistance(p,b),0)/a.length,ba=b.reduce((s,p)=>s+uaNearestDistance(p,a),0)/b.length,mean=(ab+ba)/2,score=uaClamp(100-mean*.34,0,100);uaPhase='done';uaSaveBest(score,score>=85);uaSay(`Symmetry drift: ${mean.toFixed(1)} px. ${score>90?'Mirror instincts unlocked.':'The reveal is the best part.'}`);}
    function uaScoreSplit(){if(uaPath.length<2){uaPhase='done';uaSaveBest(0);return;}const poly=uaPolygonForSplit(),a=uaPath[0],b=uaPath[uaPath.length-1],one=uaPolyClip(poly,a,b,true),two=uaPolyClip(poly,a,b,false),area1=uaArea(one),area2=uaArea(two),total=area1+area2;if(total<1){uaPhase='done';uaSaveBest(0);uaSay('Your cut missed the shape. Try crossing it from edge to edge.');return;}const ratio=Math.min(area1,area2)/total,score=uaClamp(100-Math.abs(.5-ratio)*200,0,100);uaPhase='done';uaSaveBest(score,score>=95);uaSay(`Split: ${(area1/total*100).toFixed(1)}% / ${(area2/total*100).toFixed(1)}%. ${score>97?'That is absurdly precise.':'Try moving the cut a little.'}`);}
    function uaScoreFit(){if(uaPath.length<8){uaPhase='done';uaSaveBest(0);uaSay('The shape needs a few more points to count.');return;}const box={x:280,y:130,w:400,h:300},area=uaArea(uaPath),ratio=area/(box.w*box.h),outside=uaPath.filter(p=>!uaPointInRect(p,box)).length/uaPath.length,score=uaClamp(100-Math.abs(.75-ratio)*130-outside*160,0,100);uaPhase='done';uaSaveBest(score,score>=85);uaSay(`You filled ${(ratio*100).toFixed(1)}% of the box. ${outside?'Wall breach! ':''}Target: 75%.`);}
    function uaScoreTrace(){if(uaGame!=='trace'||uaPhase!=='draw')return;const draw=uaPath,target=uaTraceTarget;if(draw.length<10){uaPhase='done';uaSaveBest(0,false);uaSay('Not enough of the path was traced. Try a longer continuous stroke.');uaUpdateUi();uaRender();return;}const a=uaResample(draw,72),b=uaResample(target,72),ab=a.reduce((sum,p)=>sum+uaNearestDistance(p,b),0)/a.length,ba=b.reduce((sum,p)=>sum+uaNearestDistance(p,a),0)/b.length,mean=(ab+ba)/2,ratio=uaLength(draw)/Math.max(1,uaLength(target)),coverage=uaClamp(Math.min(ratio,1/Math.max(.01,ratio)),0,1),score=uaClamp(100-mean*.42-Math.abs(1-ratio)*18,0,100);uaPhase='done';uaSaveBest(score,score>=82&&coverage>.55);uaSay(`Trace accuracy: ${score.toFixed(1)}%. ${score>=82?'Reference passed.':'The line drifted. Try again.'}`);uaUpdateUi();uaRender();}
    function uaPointerDown(e){if(uaPhase!=='draw'||uaPointer!==null)return;if(uaGame==='one'&&uaOneProgress>=uaOnePoints.length)return;const p=uaPoint(e);if(uaGame==='bridge'&&(p.x<230||p.x>710)){uaSay('Keep the bridge between the two platform edges.');return;}uaPointer=e.pointerId;uaPath=[p];if(uaGame==='one'&&uaOneProgress===0&&uaOnePoints.length&&uaDist(p,uaOnePoints[0])<34)uaOneProgress=1;try{uaCanvas.setPointerCapture(e.pointerId);}catch(_){}e.preventDefault();uaRender();}
    function uaPointerMove(e){if(uaPointer!==e.pointerId||uaPhase!=='draw')return;const p=uaPoint(e),last=uaPath[uaPath.length-1];if(uaDist(p,last)<2)return;if(uaGame==='split'){if(uaPath.length<2)uaPath.push(p);else uaPath[1]=p;}else{uaPath.push(p);if(uaPath.length>1600)uaPath=uaPath.filter((_,i)=>i%2===0);}if(uaGame==='one'){while(uaOneProgress<uaOnePoints.length&&uaDist(p,uaOnePoints[uaOneProgress])<34)uaOneProgress++;if(uaOneProgress>=uaOnePoints.length)uaFinishOne(true);}if(uaGame==='bridge'){uaBridgeLength=uaLength(uaPath);if(uaBridgeLength>450){uaPath.pop();uaBridgeLength=uaLength(uaPath);uaSay('Ink budget reached. 450 pixels maximum.');}}uaRender();}
