    function uaBridgeSurface(x){let y=null;if(x<=280)y=420;else if(x>=680)y=420;for(let i=1;i<uaBridgeRamp.length;i++){const a=uaBridgeRamp[i-1],b=uaBridgeRamp[i],min=Math.min(a.x,b.x),max=Math.max(a.x,b.x);if(Math.abs(b.x-a.x)<1||x<min||x>max)continue;const t=(x-a.x)/(b.x-a.x),line=a.y+(b.y-a.y)*t;if(y===null||line<y)y=line;}return y;}
    function uaStartBridge(){if(uaBridgeRamp.length<2){uaSay('Draw a bridge across the gap first.');return;}if(uaBridgeLength>450){uaSay('The bridge exceeds its ink budget.');return;}uaBridgeBall={x:120,y:407,vx:2.9,vy:0};uaPhase='running';uaSay('Marble released! Watch the ramp.');uaEnsureLoop();}
    function uaStepBridge(){const b=uaBridgeBall;if(!b)return;b.vy=Math.min(12,b.vy+.34);const prevY=b.y;b.x+=b.vx;b.y+=b.vy;const surface=uaBridgeSurface(b.x);if(surface!==null&&prevY+13<=surface+9&&b.y+13>=surface){b.y=surface-13;b.vy=0;if(b.x>280&&b.x<680){const seg=uaBridgeRamp.find((s,i)=>i>0&&b.x>=Math.min(uaBridgeRamp[i-1].x,s.x)&&b.x<=Math.max(uaBridgeRamp[i-1].x,s.x));} }
      if(b.x>770&&b.y>325&&b.y<420){uaPhase='done';const score=uaClamp(100-uaBridgeLength/450*32,0,100);uaSaveBest(score,true);uaSay(`MARBLE DELIVERED! Ramp cost ${Math.round(uaBridgeLength)} ink. Efficiency: ${score.toFixed(1)}%.`);return;}
      if(b.y>570||b.x>955||b.x<0||performance.now()-uaStartedAt>12000){uaPhase='done';uaSaveBest(Math.max(0,20-uaBridgeLength/35));uaSay('The marble missed the cup. Change the ramp and try again.');}}
    function uaStartBridgeFromAction(){uaStartedAt=performance.now();uaStartBridge();}
    function uaRetry(){uaSelectGame(uaGame);uaStartRound();}
    function uaSaveCard(){if(uaLastScore===null)return;const card=document.createElement('canvas');card.width=1000;card.height=620;const c=card.getContext('2d');const grad=c.createLinearGradient(0,0,1000,620);grad.addColorStop(0,'#111722');grad.addColorStop(1,'#24223e');c.fillStyle=grad;c.fillRect(0,0,1000,620);c.strokeStyle='rgba(216,255,79,.35)';c.lineWidth=3;c.strokeRect(28,28,944,564);c.fillStyle='#d8ff4f';c.font='700 26px ui-monospace,monospace';c.fillText('UMBRA / THE DRAWING ARCADE',72,100);c.fillStyle='#f3f5ff';c.font='800 58px system-ui,sans-serif';c.fillText(uaGames[uaGame].title,72,205);c.fillStyle='#d8ff4f';c.font='900 132px ui-monospace,monospace';c.fillText(`${uaLastScore.toFixed(1)}%`,70,390);c.fillStyle='#aeb9cc';c.font='24px system-ui,sans-serif';c.fillText(`PERSONAL BEST  ${Number.isFinite(uaBestScores[uaGame])?uaBestScores[uaGame].toFixed(1)+'%':'—'}`,76,465);c.fillText('A local challenge. A very human hand.',76,520);c.fillStyle='#8a96aa';c.font='16px ui-monospace,monospace';c.fillText(new Date().toLocaleDateString(),76,558);card.toBlob(blob=>{if(!blob){uaSay('Could not create the score card in this browser.');return;}const url=URL.createObjectURL(blob);uaDownloadUrls.push(url);const a=document.createElement('a');a.href=url;a.download=`umbra-${uaGame}-${uaLastScore.toFixed(1)}.png`;a.click();setTimeout(()=>{URL.revokeObjectURL(url);uaDownloadUrls=uaDownloadUrls.filter(x=>x!==url);},10000);uaSay('Score card saved as a PNG.');},'image/png');}
    function uaHandleAction(action){if(action==='start'){if(uaGame==='bridge'&&uaBridgeRamp.length>1&&uaPhase==='draw')uaStartBridgeFromAction();else uaStartRound();}else if(action==='retry')uaRetry();else if(action==='card')uaSaveCard();else if(action==='sound'){uaSound=!uaSound;uaUpdateUi();if(uaSound)uaBeep();}}
    function uaDispose(){uaStopLoop();uaPointer=null;uaParticles=[];if(uaAudio){try{uaAudio.close();}catch(_){}uaAudio=null;}for(const url of uaDownloadUrls)try{URL.revokeObjectURL(url);}catch(_){}uaDownloadUrls=[];}
    if(uaCanvas&&uaCtx){uaCanvas.addEventListener('pointerdown',uaPointerDown);uaCanvas.addEventListener('pointermove',uaPointerMove);uaCanvas.addEventListener('pointerup',uaPointerUp);uaCanvas.addEventListener('pointercancel',e=>{if(uaPointer===e.pointerId){uaPointer=null;uaPath=[];uaSay('Stroke cancelled.');uaRender();}});uaSelectGame('circle');}
    function setUmbraStartOpen(open){const menu=q('[data-u-start]'),toggle=q('[data-u-start-toggle]');if(!menu||!toggle)return;const next=Boolean(open);menu.hidden=!next;toggle.setAttribute('aria-expanded',String(next));toggle.setAttribute('aria-label',next?'Close UMBRA Start menu':'Open UMBRA Start menu');}
    function openWindow(id){const w=q(`[data-u-window="${id}"]`);if(!w)return;if(id==='new'){w.querySelector('[data-u-new-width]').value=doc.width;w.querySelector('[data-u-new-height]').value=doc.height;}w.hidden=false;w.classList.remove('is-minimized','is-maximized');w.style.zIndex=String(++zCounter);activeTaskWindow=id;$$u('[data-u-window]').forEach(item=>item.classList.toggle('is-active',item===w));q('.umbra-editor-window')?.classList.remove('is-active');updateTaskTabs();if(id==='layers')updateLayerList();if(id==='filters')syncUI();if(id==='assets')updateAssetList();if(id==='transform'){q('[data-u-transform-scale]').value=100;q('[data-u-transform-rotation]').value=0;q('[data-u-transform-x]').value=0;q('[data-u-transform-y]').value=0;q('[data-u-transform-flip-x]').checked=false;q('[data-u-transform-flip-y]').checked=false;}if(id==='settings')syncUmbraAppearanceSettings();if(id==='arcade'){uaUpdateUi();uaRender();}setUmbraStartOpen(false);}
