        if(hasArtwork||userTouched){const project=serialize(),size=JSON.stringify(project).length;if(size>24*1024*1024)throw new Error('This layered UMBRA project exceeds the Kernel transfer limit. Use Export .umbra for large projects; the palette can still be shared.');outputs.unshift({type:'umbra/project',title:`UMBRA project · ${doc.name||'Untitled'}`,data:project,metadata:{width:doc.width,height:doc.height,layers:layers.length}});}
