    let dbPromise=null,dbMode='IDB',currentId='main',workspaces=[],workspace={id:'main',name:'Untitled project',nodes:[],edges:[],view:{x:0,y:0,scale:1},updated:Date.now()};
    let selectedId=null,connectSource=null,gravity=true,panMode=false,pan=null,nodeDrag=null,zoom=1,tx=0,ty=0,saveTimer=0,gravityWorker=null,gravityBlobUrl='',autoEdges=[],toastTimer=0,destroyed=false;
