      const sourceNodes=Array.isArray(raw.nodes)?raw.nodes.slice(0,MAX_NODES):[],idMap=new Map(),ambiguousSourceIds=new Set(),usedNodeIds=new Set(),usedAssetIds=new Set(),nodes=[];
      const uniqueNodeId=preferred=>{let id=/^a_[a-z0-9]{1,20}_[a-z0-9]{4,12}$/i.test(String(preferred||''))?String(preferred):uidA();while(usedNodeIds.has(id))id=uidA();usedNodeIds.add(id);return id;};
