    function mapImportedSourceNodeId(sourceId,targetId,idMap,ambiguousSourceIds){
      const key=String(sourceId||'');
      if(!key||ambiguousSourceIds.has(key))return;
      if(idMap.has(key)){idMap.delete(key);ambiguousSourceIds.add(key);return;}
      idMap.set(key,targetId);
    }
