        workspaces.push(base);workspace=base;currentId=base.id;clearAetherHistory();refreshWorkspaceSelect();zoom=1;tx=0;ty=0;selectedId=null;connectSource=null;autoEdges=[];
        renderNodes();fitMesh();queueGravity();
        await persistWorkspace();
        await updateStorageEstimate();
