    function openNode(id){const n=workspace.nodes.find(x=>x.id===id);if(!n)return;if(n.type==='link'||n.type==='api'){const match=String(n.url||'').match(/^curioid:\/\/(app|world)\/([a-z0-9-]+)$/i);if(!match){say('This is an external reference. CURIOID keeps it as information and does not open outside websites.');return;}if(match[1].toLowerCase()==='app')window.CurioidDoors98OpenApp?.(match[2]);else window.CurioidNavigateToProject?.(match[2]);return;}if(n.type==='file'){getAsset(n.asset).then(blob=>{if(blob)downloadBlob(blob,n.fileName||n.title);}).catch(error=>say(`Could not open ${n.fileName||n.title}: ${String(error?.message||error).slice(0,220)}`));return;}const ok=copyText(n.content||n.title);ok.then?ok.then(v=>say(v?'Saved node context to the CURIOID clipboard.':'CURIOID clipboard unavailable.')):say(ok?'Saved node context to the CURIOID clipboard.':'CURIOID clipboard unavailable.');}
