    async function createWorkspace(){
      if(workspaces.length>=80){say('Workspace limit: 80 projects. Export an older project and delete it before creating another.');return;}
      await persistWorkspace();
      const previous={workspace,currentId,selectedId,connectSource,autoEdges,zoom,tx,ty};
      const created=makeWorkspace(`Project ${workspaces.length+1}`);
      workspace=created;workspaces.push(created);currentId=created.id;selectedId=null;connectSource=null;autoEdges=[];clearAetherHistory();zoom=1;tx=0;ty=0;
      try{
        await persistWorkspace();
        refreshWorkspaceSelect();renderNodes();fitMesh();selectNode(null);say('New project workspace created.');
      }catch(error){
        workspaces=workspaces.filter(item=>item.id!==created.id);
        workspace=previous.workspace;currentId=previous.currentId;selectedId=previous.selectedId;connectSource=previous.connectSource;autoEdges=previous.autoEdges;zoom=previous.zoom;tx=previous.tx;ty=previous.ty;
        refreshWorkspaceSelect();renderNodes();updateViewFromSaved();
        throw error;
      }
    }
    async function deleteWorkspace(){
      if(workspaces.length<=1){say('Keep at least one workspace. This last project cannot be deleted.');return;}
      const target=workspace;
      if(!window.confirm(`Delete project “${target.name}” and its ${(target.nodes||[]).length} node(s) and attachments? This cannot be undone.`))return;
      clearTimeout(saveTimer);
      // Save the active record first, then commit the index change in the storage
      // mode that currently owns the authoritative workspace snapshot.
      await persistWorkspace();
      const remaining=workspaces.filter(item=>item.id!==target.id);
      try{
        if(dbMode==='LOCAL FALLBACK')writeWorkspaceFallback(remaining);
        else await idbDeleteWorkspaceIfRevision(target.id,curioidReadStorageRevision(target,'Aether workspace selected for deletion'));
      }catch(error){if(error?.name==='AetherRevisionConflict')workspaceConflict=true;if(error?.name==='AetherStorageIntegrityError'){workspaceConflict=true;workspaceStorageReadOnly=true;updateStorageLabels();}say(error.message||'Workspace deletion could not be committed.');return;}
      workspaces=remaining;
      workspace=safeJsonClone(workspaces.slice().sort((a,b)=>(b.updated||0)-(a.updated||0))[0]);
      currentId=workspace.id;selectedId=null;connectSource=null;autoEdges=[];clearAetherHistory();
      refreshWorkspaceSelect();renderNodes();updateViewFromSaved();queueGravity();selectNode(null);
      let attachmentFailures=0;
      for(const node of target.nodes||[])if(node.asset){
        if(dbMode!=='INDEXEDDB'){attachmentFailures++;continue;}
        try{await removeAsset(node.asset);}catch(_){attachmentFailures++;}
      }
      say(`Deleted project ${target.name}. Opened ${workspace.name}.${attachmentFailures?` ${attachmentFailures} attachment(s) were retained for safe cleanup.`:''}`);
    }
