        const bytes=decodePackageBase64(item.content);ensureCurrent();if(!Number.isSafeInteger(Number(item.size))||Number(item.size)<0||bytes.byteLength!==Number(item.size))throw new Error(`File size does not match the package declaration: ${path}`);
        total+=bytes.byteLength;if(total>16*1024*1024)throw new Error('The decoded package exceeds the 16 MB source-file limit.');
