      if(!releaseImportPackage){const empty=document.createElement('p');empty.className='aura-app-foot';empty.textContent='No package inspected. Choose a .curioidproject file to validate its paths, sizes and hashes before extracting anything.';host.replaceChildren(empty);return;}
      const pack=releaseImportPackage,summary=document.createElement('div'),project=document.createElement('b'),stats=document.createElement('span'),verification=document.createElement('small'),files=document.createElement('div');summary.className='aura-import-package-summary';project.textContent=String(pack.projectTitle||'Untitled project');stats.textContent=`v${String(pack.projectVersion||'unspecified')} · ${pack.files.length} files · ${(pack.totalBytes/1048576).toFixed(2)} MB`;verification.textContent=`${pack.verified} hash(es) verified · ${pack.unverified} unchecked or unsigned file(s)`;summary.append(project,stats,verification);files.className='aura-import-package-files';pack.files.forEach((item,index)=>{const article=document.createElement('article'),details=document.createElement('div'),name=document.createElement('b'),meta=document.createElement('small'),save=document.createElement('button');name.textContent=String(item.path||'Unnamed file');meta.textContent=`${String(item.mimeType||'application/octet-stream')} · ${(Number(item.size||0)/1024).toFixed(1)} KB · ${String(item.integrity||'not checked')}`;save.type='button';save.dataset.releaseImportDownload=String(index);save.textContent='SAVE TO VAULT';details.append(name,meta);article.append(details,save);files.append(article);});const actions=document.createElement('div'),clear=document.createElement('button'),note=document.createElement('p');actions.className='aura-app-actions';clear.type='button';clear.dataset.auraAction='release-import-clear';clear.textContent='CLEAR PACKAGE PREVIEW';actions.append(clear);note.className='aura-app-foot';note.textContent='Inspection only. Files are saved one at a time after you select SAVE FILE. Folder structure is shown for reference; individual artifacts are stored in Browser Vault. No file is executed, installed or uploaded.';fragment.append(summary,files,actions,note);host.replaceChildren(fragment);
