    function benchTick(gen,win){if(auraBenchmark.generation!==gen||!auraBenchmark.running)return;const now=performance.now(),remaining=Math.max(0,(auraBenchmark.deadline-now)/1000),timer=benchPanel(win)?.querySelector('[data-bench-clock]');if(timer)timer.textContent=remaining.toFixed(1)+' s';if(remaining<=0){if(auraBenchmark.mode==='typing'||auraBenchmark.mode==='click'){const score=auraBenchmark.mode==='typing'?Math.round(auraBenchmark.score):auraBenchmark.correct;benchComplete(win,`${auraBenchmark.mode==='typing'?'Typing Sprint':'Click Sprint'} complete. Score: ${score}${auraBenchmark.mode==='typing'?' WPM':' hits'}.`,score);return;}benchFail(win,'Time expired. Start another round and try again.');return;}benchSchedule(gen,()=>benchTick(gen,win),100);}
