    function nextNback(win){const symbol=benchStage(win)?.querySelector('[data-bench-nback-symbol]'),prior=benchStage(win)?.querySelector('[data-bench-nback-prior]'),previous=benchStage(win)?.querySelector('[data-bench-nback-previous]');auraBenchmark.current=auraBenchmark.sequence[auraBenchmark.index+2];auraBenchmark.currentMatch=auraBenchmark.current===auraBenchmark.sequence[auraBenchmark.index];if(prior)prior.textContent=auraBenchmark.sequence[auraBenchmark.index];if(previous)previous.textContent=auraBenchmark.sequence[auraBenchmark.index+1];if(symbol)symbol.textContent=auraBenchmark.current;benchStatus(win,`TRIAL ${auraBenchmark.index+1} / 20 · ${auraBenchmark.correct} correct`);}
    function benchTrail(win){const size=4,count=Math.min(16,12+Math.min(4,auraBenchmark.level-1)),symbols=[];for(let i=1;i<=count;i++)symbols.push(i%2?String((i+1)/2):String.fromCharCode(64+i/2));const positions=Array.from({length:16},(_,i)=>i);for(let i=15;i>0;i--){const j=benchRandomInt(i+1);[positions[i],positions[j]]=[positions[j],positions[i]];}const order=positions.slice(0,count);auraBenchmark.items=symbols;auraBenchmark.sequence=order;auraBenchmark.index=0;const wrap=benchStageWrap('TRAIL SWITCH',`Connect 1 → A → 2 → B and continue. Complete all ${count} nodes in order.`),grid=benchNode('div','aura-bench-grid');grid.style.setProperty('--bench-columns','4');for(let i=0;i<16;i++){const ix=order.indexOf(i),b=benchButton(ix<0?'':symbols[ix],'trail',ix);b.disabled=ix<0;b.classList.toggle('is-empty',ix<0);grid.append(b);}wrap.append(grid);benchSetStage(win,wrap);benchStatus(win,'Find the next number or letter.');}
