    function auraBenchmarkInput(target){const win=target.closest('[data-aura-window="recreation-office"]');if(!win||activeArcadeMode!=='benchmark-bureau'||!auraBenchmark.running)return;if(target.matches('[data-bench-typing-input]')){const typed=target.value,correct=[...typed].filter((c,i)=>c===auraBenchmark.target[i]).length;const wpm=Math.round((correct/5)/Math.max(.1,(performance.now()-auraBenchmark.startedAt)/60000));auraBenchmark.score=wpm;benchStatus(win,`${wpm} provisional WPM · ${correct}/${typed.length} characters match the passage.`);}}
