    function updateAuraTaskTabs(){qa('[data-aura-task]').forEach(tab=>{const win=activeWindows.get(tab.dataset.auraTask),minimized=!win||win.hidden||win.classList.contains('aura-minimized'),active=tab.dataset.auraTask===activeAuraWindow&&!minimized;tab.classList.toggle('is-active',active);tab.classList.toggle('is-minimized',minimized);tab.setAttribute('aria-pressed',String(active));});}
