    function openApp(id){if(!auraApps.some(a=>a[0]===id))return;let win=activeWindows.get(id);if(!win)win=buildWindow(id);focusAuraWindow(win);setStartMenuOpen(false);}const previousAuraOpenApp=window.CurioidAuraOpenApp;const auraOpenAppBridge=id=>{if(!root.isConnected||!auraApps.some(app=>app[0]===id))return false;openApp(id);return true;};window.CurioidAuraOpenApp=auraOpenAppBridge;
    function removeWindow(id){const win=activeWindows.get(id);if(!win)return;if(id==='critiquedaemon'){minimizeAuraWindow(win);return;}if(id==='aetherdaw')stopDaw();if(id==='recreation-office')clearArcadeTimers();const wasActive=activeAuraWindow===id;win.remove();activeWindows.delete(id);q(`[data-aura-task="${id}"]`)?.remove();if(wasActive){activeAuraWindow='';const next=[...activeWindows.values()].filter(item=>!item.hidden&&!item.classList.contains('aura-minimized')).sort((a,b)=>(Number(b.style.zIndex)||0)-(Number(a.style.zIndex)||0))[0];if(next)focusAuraWindow(next);}updateAuraTaskTabs();}
    function toggleAmbient(){if(ambientOsc){ambientOsc.stop();ambientOsc.disconnect();ambientGain?.disconnect();ambientOsc=null;ambientGain=null;qa('[data-aura-action="ambient"]').forEach(b=>b.setAttribute('aria-pressed','false'));q('[data-aura-hum-state]').textContent='OFF';const control=q('[data-aura-control-hum]');if(control)control.textContent='OFF';say('Studio atmosphere disabled. Silence has been formally approved.');return;}try{const AC=window.AudioContext||/** @type {Window & {webkitAudioContext?: typeof AudioContext}} */ (window).webkitAudioContext;if(!AC)throw new Error('Web Audio is unavailable.');ambientContext=ambientContext||new AC();if(ambientContext.state==='suspended')ambientContext.resume();ambientOsc=ambientContext.createOscillator();ambientGain=ambientContext.createGain();ambientOsc.type='sine';ambientOsc.frequency.value=220;ambientGain.gain.setValueAtTime(.0001,ambientContext.currentTime);ambientGain.gain.setTargetAtTime(.022,ambientContext.currentTime,.08);ambientOsc.connect(ambientGain);ambientGain.connect(ambientContext.destination);ambientOsc.start();qa('[data-aura-action="ambient"]').forEach(b=>b.setAttribute('aria-pressed','true'));q('[data-aura-hum-state]').textContent='ON';const control=q('[data-aura-control-hum]');if(control)control.textContent='ON';say('The low studio hum is active at 220 Hz. Adjust your system volume to taste.');}catch(e){say(e.message||'Audio could not be initialized.');}}
    function stopDaw(){try{dawOsc?.stop();}catch(_){}try{dawLfo?.stop();}catch(_){}[dawOsc,dawLfo,dawGain,dawLfoDepth].forEach(n=>{try{n?.disconnect();}catch(_){}});dawOsc=dawLfo=dawGain=dawLfoDepth=null;const state=q('[data-aura-daw-state]');if(state)state.textContent='OUTPUT STANDBY';}
    function updateDawGain(){if(!dawGain||!dawContext)return;const active=trackState.filter(Boolean).length,reverb=Number(q('[data-aura-reverb]')?.value||0)/100;const volume=Math.max(0,active/128)*(.018+reverb*.075);dawGain.gain.setTargetAtTime(volume,dawContext.currentTime,.06);const out=q('[data-aura-track-count]');if(out)out.textContent=`${active} / 128`;const rev=q('[data-aura-reverb-out]');if(rev)rev.textContent=`${Math.round(reverb*100)}%`;}
    async function startDaw(){try{const AC=window.AudioContext||/** @type {Window & {webkitAudioContext?: typeof AudioContext}} */ (window).webkitAudioContext;if(!AC)throw new Error('Web Audio is unavailable.');dawContext=dawContext||new AC();if(dawContext.state==='suspended')await dawContext.resume();stopDaw();dawOsc=dawContext.createOscillator();dawGain=dawContext.createGain();dawLfo=dawContext.createOscillator();dawLfoDepth=dawContext.createGain();dawOsc.type='sine';dawOsc.frequency.value=261.6256;dawGain.gain.value=.025;dawLfo.frequency.value=1.2;dawLfoDepth.gain.value=.012;dawOsc.connect(dawGain);dawLfo.connect(dawLfoDepth);dawLfoDepth.connect(dawGain.gain);dawGain.connect(dawContext.destination);dawOsc.start();dawLfo.start();updateDawGain();q('[data-aura-daw-state]').textContent='C4 / 72 BPM / OUTPUT ACTIVE';say('AetherDAW output is now stable at C4.');}catch(e){say(e.message||'Audio could not be initialized.');}}
    function renderPaletteArchive(scope=root){const host=$('[data-aura-palette-archive]',scope);if(!host)return;const start=Math.max(0,savedPalettes.length-5),entries=savedPalettes.slice(start).map((item,index)=>({item,index:index+start})).reverse();host.replaceChildren();if(!entries.length){const empty=document.createElement('small');empty.textContent='No palette studies archived.';host.appendChild(empty);return;}entries.forEach(({item,index})=>{const row=document.createElement('div');row.className='aura-archive-entry';const label=document.createElement('span'),colors=Array.isArray(item.colors)?item.colors:[];label.textContent=`${String(item.name??'')} · ${colors.map(color=>String(color??'')).join(' / ')}`;const remove=document.createElement('button');remove.type='button';remove.dataset.auraDeletePalette=String(index);remove.setAttribute('aria-label','Delete saved palette');remove.textContent='×';row.append(label,remove);host.appendChild(row);});}
    function drawCube(canvas){if(!canvas)return;const c=canvas.getContext('2d');if(!c)return;const w=canvas.width,h=canvas.height;c.clearRect(0,0,w,h);c.fillStyle='#151719';c.fillRect(0,0,w,h);c.strokeStyle='rgba(255,255,255,.055)';c.lineWidth=1;for(let x=24;x<w;x+=32){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke();}for(let y=24;y<h;y+=32){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke();}const sx=Math.sin(cubeAngles.x),cx=Math.cos(cubeAngles.x),sy=Math.sin(cubeAngles.y),cy=Math.cos(cubeAngles.y);const pts=[];for(let z of [-1,1])for(let y of [-1,1])for(let x of [-1,1]){const rx=x*cy-z*sy,rz=x*sy+z*cy,ry=y*cx-rz*sx,rz2=y*sx+rz*cx,scale=175/(3.6-rz2*.36);pts.push([w/2+rx*scale,h/2+ry*scale]);}const order=[[0,1],[0,2],[0,4],[1,3],[1,5],[2,3],[2,6],[3,7],[4,5],[4,6],[5,7],[6,7]];c.lineWidth=3;c.strokeStyle='#aeb2b2';order.forEach(([a,b])=>{c.beginPath();c.moveTo(...pts[a]);c.lineTo(...pts[b]);c.stroke();});const faces=[[0,1,3,2],[4,5,7,6],[0,1,5,4],[2,3,7,6],[0,2,6,4],[1,3,7,5]];faces.forEach((face,i)=>{c.beginPath();face.forEach((p,j)=>j?c.lineTo(...pts[p]):c.moveTo(...pts[p]));c.closePath();c.fillStyle=['rgba(220,220,220,.16)','rgba(180,180,180,.13)','rgba(245,245,245,.12)','rgba(130,130,130,.16)','rgba(205,205,205,.1)','rgba(160,160,160,.18)'][i];c.fill();c.strokeStyle='#c3c6c5';c.stroke();});c.fillStyle='#9da2a1';c.font='13px monospace';c.fillText('UNIT VOLUME / 1.000 M³',20,h-20);}
    function playChime(){try{const AC=window.AudioContext||/** @type {Window & {webkitAudioContext?: typeof AudioContext}} */ (window).webkitAudioContext;dawContext=dawContext||new AC();if(dawContext.state==='suspended')dawContext.resume();const o=dawContext.createOscillator(),g=dawContext.createGain();o.type='sine';o.frequency.value=660;g.gain.setValueAtTime(.025,dawContext.currentTime);g.gain.exponentialRampToValueAtTime(.0001,dawContext.currentTime+.14);o.connect(g);g.connect(dawContext.destination);o.start();o.stop(dawContext.currentTime+.15);}catch(_){}}
    function defaultPersona(){return{name:'Elias Venn',dept:'Continuity Review',goal:'Reconciliation of prior assignments',trait:'Quietly procedural',desc:'The employee’s previous desk assignment remains occupied in all records. No reassignment has been requested.'};}
    function makePersona(){const departments=['Zoning Review','Curb Alignment','Municipal Setback Compliance','Planning Documentation','Permit Continuity'];const goals=['Accurate boundary records','Timely form distribution','Consistent corridor classification','Reconciliation of duplicate site plans','Continuity of unassigned office space'];const traits=['Quietly procedural','Dependably neutral','Consistent in all recorded circumstances','Comfortable with subcommittees','No personal variance requiring review'];const first=['Elias','Mara','Jonas','Irena','Nadia','Tomas','Ansel','Vera'];const surnames=['Mercer','Pritchard','Bell','Wexler','Hollis','Tennant','Pike'];const item={name:`${pick(first)} ${pick(surnames)}`,dept:pick(departments),goal:pick(goals),trait:pick(traits),desc:'The subject’s previous record was reviewed. No discrepancy was identified. The previous record was not available for comparison.'};return item;}
    function paintPersona(scope,persona){const set=(sel,v)=>{const el=$(sel,scope);if(el)el.textContent=v;};set('[data-aura-persona-name]',persona.name);set('[data-aura-persona-dept]',persona.dept);set('[data-aura-persona-goal]',persona.goal);set('[data-aura-persona-trait]',persona.trait);set('[data-aura-persona-desc]',persona.desc);}
