    function compileSyntax(scope){const source=$('[data-aura-source]',scope)?.value.trim()||'The moon wept silver';let result;if(/moon.{0,20}wept.{0,20}silver/i.test(source))result='Q3 lunar liquidity exceeded projected benchmarks.';else{const words=source.toLowerCase().replace(/[^a-z0-9\s-]/g,' ').split(/\s+/).filter(Boolean);const anchor=(words.find(w=>w.length>4&& !['there','their','about','would','could','should','silver','wept'].includes(w))||'creative').replace(/(^|[- ])\w/g,m=>m.toUpperCase());const action=/\b(wept|cried|fell|broke|burned|dreamed|sang|shouted|whispered)\b/i.test(source)?'emotional variance':'unstructured expression';result=`Q3 ${anchor} utilization exceeded projected benchmarks; ${action} has been normalized into scalable operational value.`;}const out=$('[data-aura-syntax-output]',scope);if(out)out.textContent=result;const gates=$$('[data-syntax-gate]',scope);gates.forEach((g,i)=>{g.classList.remove('cleared');setTimeout(()=>g.classList.add('cleared'),i*28);});bumpDeliverables();say('14-layer language normalization completed.');return result;}
